\cite{ICd1,ICd3}\label{EPdef1}
Let ${\overline{\mathfrak{w}}}^*\in\mathscr{H}$ is an equilibrium point of
	\eqref{eq:system} if
	\begin{equation}
		\label{eq:equilibrium}
		 \Sigma(s,{\overline{\mathfrak{w}}}^*) = 0, \quad \forall \, s > s_0.
	\end{equation}. Then  model \eqref{eq:system} is said to be
\begin{enumerate}
	\item \texttt{Lyapunov stability:}  
	For every $\mathcal{E}>0$, $\exists$ $\chi=\chi(\mathcal{E},s_0)$ satisfying
	\begin{equation}
		\label{eq:lyapunov_stable}
		\|w_0-{\overline{\mathfrak{w}}}^*\|<\chi\;\Rightarrow\;
		\|w(s)-{\overline{\mathfrak{w}}}^*\|<\mathcal{E}, \quad \forall\, s>s_0.
	\end{equation}
	\item \texttt{FT convergence}, if  $\exists$ settling-time function $\mathcal{T}:\mathscr{H}\setminus\{\overline{\mathfrak{w}}^{*}\}\to(0,\infty) \ (\text{i.e.}\ \mathcal{T} < \infty)$ satisfying $\forall\, w(0)\in\mathscr{H}\setminus\{\overline{\mathfrak{w}}^{*}\}$
	\[
	w(s)=\overline{\mathfrak{w}}^{*},
	\qquad
	\forall\, s\ge \mathcal{T}(w(0)),
	\]
	where $\mathcal{T}(w(0))<\infty$.
	\item \texttt{\rm{FxT} stable}, if it is FT stable with $\exists$ an upper bound $\mathcal{T}_{\max} < \infty$ satisfying
	\[
	\sup_{w_0 \in \mathscr{H}} \mathcal{T}(w_0) \leq \mathcal{T}_{\max}.
	\]
\end{enumerate}

\label{IncCL1}
Suppose assumption $\eqref{ICAsmmain}$ hold. Let
\(
\vartheta_1=\frac{1+\lambda_1}{2},\quad
\vartheta_2=\frac{1+\lambda_2}{2},
\)
\(
m_1=
2^{\vartheta_1}
\frac{(1- \aleph)}{\mathcal (1+\aleph)^{1-\lambda_1}},
\) and \(
m_2=
2^{\vartheta_2}(1- \aleph)^{\lambda_2}.
\)
where $\varpi_0>0$, $ \varrho_0>0$, and $\tau>0$.

\begin{enumerate}[label=\textnormal{(\roman*)}]

\item If one selects $\phi_1(s)=\varpi_0$ and $\phi_2(s)= \varrho_0$ in TVCNDM~\eqref{INFxTM}, then, $w(s)$ reaches the equilibrium point ${\overline{\mathfrak{w}}}^*$ in FxT, with the settling-time bound given by
\begin{equation}\label{T1}
T \le 
\frac{1}{\varpi_0 m_1 (1-\vartheta_1)}
+
\frac{1}{ \varrho_0 m_2 (\vartheta_2-1)}.
\end{equation}

\item If one selects 
\(
\phi_1(s)=\frac{\varpi_0}{t+\tau} \ \text{and}\ 
\phi_2(s)=\frac{ \varrho_0}{t+\tau}
\)
in TVCNDM~\eqref{INFxTM}, then, $w(s)$ reaches the equilibrium point ${\overline{\mathfrak{w}}}^*$ in FxT, with the settling-time bound given by
\begin{equation}\label{T2}
T \le 
\tau \exp\!\left(
\frac{1}{\varpi_0 m_1 (1-\vartheta_1)}
+
\frac{1}{ \varrho_0 m_2 (\vartheta_2-1)}
\right)
-\tau.
\end{equation}

\item If one selects 
\(
\phi_1(s)=\varpi_0 
\ \text{and} \
\phi_2(s)=\frac{ \varrho_0}{t+\tau}
\)
in TVCNDM~\eqref{INFxTM}, then, $w(s)$ reaches the equilibrium point ${\overline{\mathfrak{w}}}^*$ in FxT, with the settling-time bound given by
\begin{equation}\label{T3}
T \le 
\tau \exp\!\left(
\frac{1}{ \varrho_0 m_2 (\vartheta_2-1)}
\right)
+
\frac{1}{\varpi_0 m_1 (1-\vartheta_1)}
-\tau.
\end{equation}

\item If one selects 
\(
\phi_1(s)=\frac{\varpi_0}{(s+\tau)^{\alpha_1}}
\ \text{and}
\ \phi_2(s)=\frac{ \varrho_0}{(s+\tau)^{\alpha_2}},
\)
where $\alpha_1 \neq 1$ and $\alpha_2 \neq 1$, s. t.
\[
\alpha=
\frac{1-\alpha_2}{ \varrho_0 m_2 (\vartheta_2-1)}
+
\tau^{1-\alpha_2}
>0,
\quad
\text{and}
\quad
\alpha^{\frac{1-\alpha_1}{1-\alpha_2}}
+
\frac{1-\alpha_1}{\varpi_0 m_1 (1-\vartheta_1)}
>0,
\]
then, $w(s)$ reaches the equilibrium point ${\overline{\mathfrak{w}}}^*$ in $\mathrm{FxT}$, with the settling-time bound given by
\begin{equation}\label{T4}
T \le 
\left(
\alpha^{\frac{1-\alpha_1}{1-\alpha_2}}
+
\frac{1-\alpha_1}{\varpi_0 m_1 (1-\vartheta_1)}
\right)^{\!\frac{1}{1-\alpha_1}}
-\tau.
\end{equation}

\end{enumerate}
